import React from 'react';
import { Typography, Box, Paper, Grid, TextField, Button, Alert } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import axiosInstance from '../../core/api/axiosConfig';

const Settings = () => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const { data: settings, isLoading } = useQuery({
    queryKey: ['settings'],
    queryFn: () => axiosInstance.get('/settings/').then(r => r.data),
  });

  const { data: profile } = useQuery({
    queryKey: ['company-profile'],
    queryFn: () => axiosInstance.get('/settings/company-profile/').then(r => r.data),
  });

  const updateSetting = useMutation({
    mutationFn: ({ key, value }) => axiosInstance.put(`/settings/${key}/`, { value }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['settings'] }),
  });

  const updateProfile = useMutation({
    mutationFn: (data) => axiosInstance.put('/settings/company-profile/update/', data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['company-profile'] }),
  });

  const [profileForm, setProfileForm] = React.useState({});

  React.useEffect(() => {
    if (profile) setProfileForm(profile);
  }, [profile]);

  if (isLoading) return <Box sx={{ p: 3 }}>Loading...</Box>;

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('nav.settings')}</Typography>

      {/* Company Profile */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom>{t('company.title')}</Typography>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <TextField fullWidth size="small" label="نام شرکت" value={profileForm.legal_name || ''}
              onChange={e => setProfileForm(p => ({ ...p, legal_name: e.target.value }))} />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField fullWidth size="small" label="تلفن" value={profileForm.phone || ''}
              onChange={e => setProfileForm(p => ({ ...p, phone: e.target.value }))} />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField fullWidth size="small" label="ایمیل" value={profileForm.email || ''}
              onChange={e => setProfileForm(p => ({ ...p, email: e.target.value }))} />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField fullWidth size="small" label="وب‌سایت" value={profileForm.website || ''}
              onChange={e => setProfileForm(p => ({ ...p, website: e.target.value }))} />
          </Grid>
          <Grid item xs={12}>
            <TextField fullWidth size="small" label="آدرس" multiline rows={2} value={profileForm.address || ''}
              onChange={e => setProfileForm(p => ({ ...p, address: e.target.value }))} />
          </Grid>
        </Grid>
        <Button variant="contained" sx={{ mt: 2 }} onClick={() => updateProfile.mutate(profileForm)}>
          {t('common.save')}
        </Button>
      </Paper>

      {/* System Settings */}
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>{t('company.title')}</Typography>
        {settings && Object.entries(settings).map(([key, value]) => (
          <Box key={key} sx={{ mb: 2 }}>
            <Typography variant="body2" color="textSecondary">{key}</Typography>
            <TextField
              size="small"
              fullWidth
              value={typeof value === 'object' ? JSON.stringify(value) : String(value || '')}
              onChange={e => updateSetting.mutate({ key, value: e.target.value })}
            />
          </Box>
        ))}
      </Paper>
    </Box>
  );
};

export default Settings;
